(21, 1, '2026-11-06 08:36:53', '2026-11-06 08:36:53', '<!-- wp:group {\"tagName\":\"header\",\"metadata\":{\"patternName\":\"online-training/header\",\"name\":\"Header\",\"categories\":[\"online-training\"]},\"align\":\"full\",\"className\":\"site-header\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"24px\",\"bottom\":\"24px\",\"left\":\"var:preset|spacing|50\",\"right\":\"var:preset|spacing|50\"}}},\"backgroundColor\":\"background-dark\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1240px\"}} -->\n<header class=\"wp-block-group alignfull site-header has-background-dark-background-color has-background\" style=\"padding-top:24px;padding-right:var(--wp--preset--spacing--50);padding-bottom:24px;padding-left:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"10px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\",\"justifyContent\":\"left\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|heading-text\"}}},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"600\"}},\"textColor\":\"heading-text\",\"fontSize\":\"large\",\"fontFamily\":\"accent\"} -->\n<p class=\"has-heading-text-color has-text-color has-link-color has-accent-font-family has-large-font-size\" style=\"font-style:normal;font-weight:600\">Literasi Digital</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:navigation {\"ref\":12,\"textColor\":\"muted-text\",\"style\":{\"typography\":{\"fontWeight\":\"500\"},\"spacing\":{\"blockGap\":\"34px\"}},\"fontSize\":\"small\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"flexWrap\":\"nowrap\"}} /--></div>\n<!-- /wp:group --></header>\n<!-- /wp:group --