(24, 1, '2026-11-06 09:44:38', '2026-11-06 09:44:38', '<!-- wp:navigation-link {\"label\":\"Konsep Etika\",\"type\":\"page\",\"id\":13,\"url\":\"http://localhost/literasi/?page_id=13\",\"kind\":\"post-type\",\"isTopLevelLink\":true,\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"Tantangan \\u0026 Kasus\",\"type\":\"page\",\"id\":14,\"url\":\"http://localhost/literasi/?page_id=14\",\"kind\":\"post-type\",\"isTopLevelLink\":true,\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"Regulasi \\u0026 UU ITE\",\"type\":\"page\",\"id\":15,\"url\":\"http://localhost/literasi/?page_id=15\",\"kind\":\"post-type\",\"isTopLevelLink\":true,\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"Tips \\u0026 Panduan\",\"type\":\"page\",\"id\":16,\"url\":\"http://localhost/literasi/?page_id=16\",\"kind\":\"post-type\",\"isTopLevelLink\":true,\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"Tentang Saya\",\"type\":\"page\",\"id\":17,\"url\":\"http://localhost/literasi/?page_id=17\",\"kind\":\"post-type\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"Kontak\",\"type\":\"page\",\"id\":18,\"url\":\"http://localhost/literasi/?page_id=18\",\"kind\":\"post-type\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} /-->', 'Menu Header', '', 'publish', 'closed', 'closed', '', 'menu-header-2', '', '', '2026-11-07 05:28:04', '2026-11-07 05:28:04', '', 0, 'http://localhost/literasi/?p=24', 0, 'wp_navigation', '', 0),
