(70, 1, '2026-11-07 04:26:25', '2026-11-07 04:26:25', '<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"saas-startup\",\"tagName\":\"header\"} /-->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"saas-startup/header-003\",\"name\":\"Header 003\",\"categories\":[\"header\"]},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-xxlarge\",\"bottom\":\"var:preset|spacing|superbspacing-xxlarge\",\"left\":\"var:preset|spacing|superbspacing-small\",\"right\":\"var:preset|spacing|superbspacing-small\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"background\":{\"backgroundImage\":{\"url\":\"http://localhost/literasi/wp-content/themes/saas-startup/assets/images/header/header-3-bg.png\",\"id\":2000,\"source\":\"file\",\"title\":\"home-banner-waves-desktop\"},\"backgroundSize\":\"contain\",\"backgroundRepeat\":\"no-repeat\",\"backgroundPosition\":\"100% 0%\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-xxlarge);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-xxlarge);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}},\"border\":{\"radius\":\"20px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"border-radius:20px;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"800px\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-1\",\"fontSize\":\"superbfont-xxlarge\"} -->\n<h1 class=\"wp-block-heading has-text-align-center has-mono-1-color has-text-color has-superbfont-xxlarge-font-size\">Cerdas &amp; Bijak Berinteraksi di Ruang Digital</h1>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\",\"contentSize\":\"500px\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-2\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-text-align-center has-mono-2-color has-text-color has-superbfont-small-font-size\">Portal literasi digital komprehensif untuk memahami batasan hukum UU ITE, etika bermedia sosial, dan pentingnya menjaga rekam jejak digital.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"},\"layout\":{\"selfStretch\":\"fill\",\"flexSize\":null}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-fill\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|superbspacing-small\",\"right\":\"var:preset|spacing|superbspacing-small\"}}},\"fontSize\":\"superbfont-small\"} -->\n<div class=\"wp-block-button is-style-fill\"><a class=\"wp-block-button__link has-superbfont-small-font-size has-custom-font-size wp-element-button\" href=\"http://localhost/literasi/?page_id=13\" style=\"padding-right:var(--wp--preset--spacing--superbspacing-small);padding-left:var(--wp--preset--spacing--superbspacing-small)\">Mulai Belajar →</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"saas-startup/layout-004\",\"name\":\"Layout 004\",\"categories\":[\"layouts\"]},\"align\":\"full\",\"className\":\"column-parent-border-radius\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-xlarge\",\"bottom\":\"var:preset|spacing|superbspacing-xlarge\",\"left\":\"var:preset|spacing|superbspacing-small\",\"right\":\"var:preset|spacing|superbspacing-small\"},\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-group alignfull column-parent-border-radius\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-xlarge);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-xlarge);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"600px\"}} -->\n<div class=\"wp-block-group alignwide\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"primary\",\"fontSize\":\"superbfont-small\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-primary-color has-text-color has-superbfont-small-font-size\">Materi Inti</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"contrast\",\"fontSize\":\"superbfont-xlarge\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-contrast-color has-text-color has-superbfont-xlarge-font-size\">3 Pilar Etika Digital</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-2\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-text-align-center has-mono-2-color has-text-color has-superbfont-small-font-size\">Kuasai tiga prinsip dasar ini untuk melindungi privasi Anda, menghargai orang lain, dan menyaring informasi yang beredar di internet.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"var:preset|spacing|superbspacing-small\",\"left\":\"var:preset|spacing|superbspacing-small\",\"right\":\"var:preset|spacing|superbspacing-small\"}}},\"backgroundColor\":\"mono-4\"} -->\n<div class=\"wp-block-column has-mono-4-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--superbspacing-small);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-small);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:icon {\"icon\":\"core/comment\",\"align\":\"center\",\"style\":{\"dimensions\":{\"width\":\"45px\"},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|filled-button-border\"}}}},\"textColor\":\"filled-button-border\"} /-->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|mono-1\"}}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-1\",\"fontSize\":\"superbfont-medium\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-mono-1-color has-text-color has-link-color has-superbfont-medium-font-size\" style=\"margin-top:0;margin-bottom:0\">Komunikasi Santun</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-xxsmall\",\"bottom\":\"0\"}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-2\",\"fontSize\":\"superbfont-xsmall\"} -->\n<p class=\"has-text-align-center has-mono-2-color has-text-color has-superbfont-xsmall-font-size\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-xxsmall);margin-bottom:0\">Berinteraksi dengan sopan, menghindari ujaran kebencian, dan menghargai opini pengguna lain.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"var:preset|spacing|superbspacing-small\",\"left\":\"var:preset|spacing|superbspacing-small\",\"right\":\"var:preset|spacing|superbspacing-small\"}}},\"backgroundColor\":\"mono-4\"} -->\n<div class=\"wp-block-column has-mono-4-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--superbspacing-small);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-small);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:icon {\"icon\":\"core/shield\",\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|filled-button-border\"}}},\"dimensions\":{\"width\":\"45px\"}},\"textColor\":\"filled-button-border\"} /-->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|mono-1\"}}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-1\",\"fontSize\":\"superbfont-medium\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-mono-1-color has-text-color has-link-color has-superbfont-medium-font-size\" style=\"margin-top:0;margin-bottom:0\">Keamanan Privasi</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-xxsmall\",\"bottom\":\"0\"}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-2\",\"fontSize\":\"superbfont-xsmall\"} -->\n<p class=\"has-text-align-center has-mono-2-color has-text-color has-superbfont-xsmall-font-size\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-xxsmall);margin-bottom:0\">Pahami cara melindungi data pribadi agar tidak bocor dan disalahgunakan di ruang publik.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"var:preset|spacing|superbspacing-small\",\"left\":\"var:preset|spacing|superbspacing-small\",\"right\":\"var:preset|spacing|superbspacing-small\"}}},\"backgroundColor\":\"mono-4\"} -->\n<div class=\"wp-block-column has-mono-4-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--superbspacing-small);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-small);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:icon {\"icon\":\"core/search\",\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|filled-button-border\"}}},\"dimensions\":{\"width\":\"45px\"}},\"textColor\":\"filled-button-border\"} /-->\n\n<!-- wp:heading {\"level\":3,\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-1\",\"fontSize\":\"superbfont-medium\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-mono-1-color has-text-color has-superbfont-medium-font-size\" style=\"margin-top:0;margin-bottom:0\">Kritis Terima Informasi</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-xxsmall\",\"bottom\":\"0\"}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"mono-2\",\"fontSize\":\"superbfont-xsmall\"} -->\n<p class=\"has-text-align-center has-mono-2-color has-text-color has-superbfont-xsmall-font-size\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-xxsmall);margin-bottom:0\">Saring sebelum sharing. Biasakan memverifikasi fakta untuk mencegah penyebaran hoaks.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"patternName\":\"saas-startup/cta-001\",\"name\":\"Call To Action 001\",\"categories\":[\"call-to-action\"]},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|superbspacing-large\",\"right\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"var:preset|spacing|superbspacing-large\",\"left\":\"var:preset|spacing|superbspacing-small\"},\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"backgroundColor\":\"mono-4\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-mono-4-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-large);padding-right:var(--wp--preset--spacing--superbspacing-small);padding-bottom:var(--wp--preset--spacing--superbspacing-large);padding-left:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"left\":\"var:preset|spacing|superbspacing-small\"}}}} -->\n<div class=\"wp-block-columns alignwide\"><!-- wp:column {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"padding\":{\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"lineHeight\":\"1.2\",\"textAlign\":\"left\"}},\"fontSize\":\"superbfont-xlarge\"} -->\n<h3 class=\"wp-block-heading has-text-align-left has-superbfont-xlarge-font-size\" style=\"line-height:1.2\">Jejak Digital Itu Abadi</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}},\"textColor\":\"mono-2\",\"fontSize\":\"superbfont-small\"} -->\n<p class=\"has-text-align-left has-mono-2-color has-text-color has-superbfont-small-font-size\">Setiap komentar, foto, dan status yang Anda unggah akan terekam selamanya di internet. Etika yang baik hari ini akan melindungi reputasi Anda di masa depan.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|superbspacing-xsmall\",\"right\":\"var:preset|spacing|superbspacing-xsmall\",\"top\":\"var:preset|spacing|superbspacing-xsmall\",\"bottom\":\"var:preset|spacing|superbspacing-xsmall\"}}},\"fontSize\":\"superbfont-small\"} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-superbfont-small-font-size has-custom-font-size wp-element-button\" href=\"http://localhost/literasi/?page_id=14\" style=\"padding-top:var(--wp--preset--spacing--superbspacing-xsmall);padding-right:var(--wp--preset--spacing--superbspacing-xsmall);padding-bottom:var(--wp--preset--spacing--superbspacing-xsmall);padding-left:var(--wp--preset--spacing--superbspacing-xsmall)\">Pelajari Selengkapnya →</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"style\":{\"spacing\":{\"blockGap\":\"15px\",\"padding\":{\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:image {\"id\":48,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"radius\":\"8px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"http://localhost/liter